code_sketch:
struct frame { uint32_t len; uint8_t kind; uint8_t payload[]; };

n = mq_receive(q, buf, sizeof buf, &prio);
if (n < (ssize_t)sizeof(struct frame) || checksum(buf, n) != 0) {
    mq_send(err_q, buf, (size_t)n, 0);      /* invalid channel */
    log_reject("malformed frame", n);
    continue;                              /* main channel stays clean */
}
